SPL_st.name='SPL'; 
SPL_st.lat=40.46;
SPL_st.lon=-106.74;
SPL_st.alt=3220;
SPL_st.env='Mt';
SPL_st.footp='Mix'; %% not sure, see answer to homogeneity
%%
SPL_rd=read_betsy_2026('C:\github_trend\raw_data\spl_neph_psap_clap',SPL_st.name); %[output:56104d36] %[output:2eb2eecc] %[output:26c20cf3]
SPL_rd_nc=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Steamboat Springs, Colorado (Storm Peak Laboratory).nc');
%%
datevec(SPL_rd.Time(1)) % Jan 2011 first year not complete, begin in 2012 %[output:745b0a46]
datevec(SPL_rd.Time(end)) % Dec 2025 %[output:1280e50d] %[output:0432c58e]
prctile(SPL_rd.U0_S11,[5 50 95]) % always < 25% OK
prctile(SPL_rd.U1_S11,[5 50 95]) % always < 25% OK --> trend in _dry not needed %[output:1f5426db]
names_rd=fieldnames(SPL_rd);
for i=1:length(names_rd)
    if startsWith(names_rd{i} ,'B')
        indNaN=SPL_rd.(names_rd{i})>9999;
SPL_rd.(names_rd{i})(indNaN)=NaN;
    end
    if endsWith(names_rd{i} ,'_dry')
        SPL_rd.(names_rd{i})=[];
    end
end
names_rd=fieldnames(SPL_rd);
plotFigControl(SPL_rd, SPL_st.name); %[output:8e97b7f0] %[output:4582334d] %[output:765b6ac7] %[output:95a70336] %[output:0d4f02e5] %[output:73ea016f] %[output:8e964daa] %[output:5dbc00e6]
%%
%Break detection scat and backscat

names_sc={'BsB0_S11', 'BsG0_S11', 'BsR0_S11','BsB1_S11','BsG1_S11','BsR1_S11'};
break_SPL_scat_BP=change_point_analysis_Def(SPL_rd,names_sc,0.05,'SPL','neph SC'); %[output:0f10549f] %[output:6cfe0b66] %[output:16d91610] %[output:4b02f2fe]
T_SPL_scat_BP=make_table_breakpoints(break_SPL_scat_BP,names_sc);

%%

names_bsc={'BbsB0_S11', 'BbsG0_S11', 'BbsR0_S11','BbsG1_S11'};
break_SPL_bscat_BP=change_point_analysis_Def(SPL_rd,names_bsc,0.05,'SPL','neph BackSC'); %[output:23d7608d] %[output:78e0ef4b] %[output:726c899e] %[output:41b5ef32]
T_SPL_bscat_BP=make_table_breakpoints(break_SPL_bscat_BP,names_bsc); %[output:3b2ac10b] %[output:57c84743] %[output:0358ae71]
%%
%BP detection for abs (only CLAP that is longer)
names_abs={'BaB0_A12_clap', 'BaG0_A12_clap', 'BaR0_A12_clap','BaG1_A12_clap'};
break_SPL_abs_BP=change_point_analysis_Def(SPL_rd,names_abs,0.05,'SPL','abs CLAP'); %[output:1526cdaa] %[output:1bf42b08] %[output:7e0fba56] %[output:602d13e5]
T_SPL_abs_BP=make_table_breakpoints(break_SPL_abs_BP,names_abs);
%%
%value computed
lambdaSC=[450;550;700];
lambdaAE=[467;528;652];
names_neph={'BsB0_S11', 'BsG0_S11', 'BsR0_S11','BsB1_S11','BsG1_S11','BsR1_S11','BbsB0_S11', 'BbsG0_S11', 'BbsR0_S11','BbsB1_S11','BbsG1_S11','BbsR1_S11'};
SPL_expSC=compute_exp_D(SPL_rd,names_neph,lambdaSC);
names_abs={'BaB0_A12_clap', 'BaG0_A12_clap', 'BaR0_A12_clap','BaB1_A12_clap','BaG1_A12_clap','BaR1_A12_clap'};
SPL_expA=compute_exp_D(SPL_rd,names_abs,lambdaAE);
SPL_exp=synchronize(SPL_expSC,SPL_expA);
SPL_SSA=compute_SSA_D(SPL_rd,{'BsG0_S11','BsG1_S11'},{'BaG0_A12_clap','BaG1_A12_clap'});

SPL_cal=synchronize(SPL_exp,SPL_SSA);
clear SPL_expSC SPL_expA SPL_exp SPL_SSA;
plotFigControl_cal(SPL_cal, SPL_st.name); %[output:606dd78b] %[output:3c1b95d7]
names_cal=fieldnames(SPL_cal);
%%
%BP detection for expSC
names_expS={'expS_bg0', 'expS_bg1'};
break_SPL_expS_BP=change_point_analysis_Def(SPL_cal,names_expS,0.05,'SPL','expS'); %[output:55866ed6] %[output:97d9f0ae] %[output:5b376b93] %[output:0d395c7c]
T_SPL_expS_BP=make_table_breakpoints_def(break_SPL_expS_BP); %[output:12973daf] %[output:4a5c1d6d] %[output:09ddd7f8] %[output:1f3c0731] %[output:224e4e52]
%%
%BP detection for SSA (only CLAP that is longer)
names_expA={'expA_bg0', 'expA_bg1'};
break_SPL_expA_BP=change_point_analysis_Def(SPL_cal,names_expA,0.05,'SPL','expA'); %[output:5b40abe0] %[output:7c974494] %[output:62b44158] %[output:8f1310e3]
T_SPL_expA_BP=make_table_breakpoints_def(break_SPL_expA_BP); %[output:5fc99047]
%%
%BP detection for SSA (only CLAP that is longer)
names_BbsF={'BbsFbg0', 'BbsFbg1'};
break_SPL_BbsF_BP=change_point_analysis_Def(SPL_cal,names_BbsF,0.05,'SPL','BbsF'); %[output:916adb09] %[output:40e18f9e] %[output:50f4ea47] %[output:922eec84]
T_SPL_BbsF_BP=make_table_breakpoints_def(break_SPL_BbsF_BP); %[output:81fc53ec] %[output:40ce2b9e] %[output:824acef2] %[output:3efdaa88] %[output:1eaa24d7] %[output:66def47b] %[output:807fdc50] %[output:413505bb]
%%
%BP detection for SSA (only CLAP that is longer)
names_SSA={'SSAG0', 'SSAG1'};
break_SPL_SSA_BP=change_point_analysis_Def(SPL_cal,names_SSA,0.05,'SPL','SSA'); %[output:507203a1] %[output:22f740ba] %[output:0f71d3f5] %[output:8b6989aa]
T_SPL_SSA_BP=make_table_breakpoints_def(break_SPL_SSA_BP); %[output:0faa47ba]
%%
% Make trend time series
% not complete 2011 for both neph and abs --> begin in 2012
% RH < 40% --> not necessary to compute RH and dry trends

SPL_tr=SPL_rd;
SPL_tr.y=year(SPL_tr.Time);

P=timerange('2012-01-01','2026-01-01');
SPL_tr=SPL_tr(P,:);

% U < 5%: no trend in U and in dry
%don't use abs: too short
names=fieldnames(SPL_tr);
c= startsWith(names,["U"]) | endsWith(names,'_dry') | endsWith(names,'psap');
N=names(c);
for i=1:length(N)
    SPL_tr.(N{i})=[];
end
%%

% compute variables
SPL_cal2=compute_exp_SSA(SPL_tr,lambdaSC, lambdaAE);
SPL_tr=outerjoin(SPL_tr, SPL_cal2);
%%

%compute scat trend on G and expS_gr
SPL_tr.BsB0_S11=[];
SPL_tr.BsR0_S11=[];
SPL_tr.BsB1_S11=[];
SPL_tr.BsR1_S11=[];

SPL_tr.BbsB0_S11=[];
SPL_tr.BbsR0_S11=[];
SPL_tr.BbsB1_S11=[];
SPL_tr.BbsR1_S11=[];

SPL_tr.expS_br0=[];
SPL_tr.expS_gr0=[];
SPL_tr.expS_br1=[];
SPL_tr.expS_gr1=[];

% compute SSA on G

% compute abs trend on 520 nm and expA_fit
SPL_tr.BaB1_A12_clap=[];
SPL_tr.BaR1_A12_clap=[];
SPL_tr.BaB0_A12_clap=[];
SPL_tr.BaR0_A12_clap=[];


SPL_tr.expA_br0=[];
SPL_tr.expA_gr0=[];
SPL_tr.expA_br1=[];
SPL_tr.expA_gr1=[];
%%
% save data in Netcdf
timetable_to_netcdf(SPL_tr, 'C:/github_trend/result/SPL/SPL_tr.nc');
%%
[SPL_result_MK,SPL_result_LMSlog,SPL_result_LMSlin]=all_trend_STN(SPL_tr, SPL_st);
plot_10y_in_two(SPL_result_MK,SPL_st,'y');
writetable(SPL_result_MK,'SPL_result_MK.txt'); %, 'delimiter',',' )
writetable(SPL_result_GSMd,'SPL_result_GSMd.txt'); 
writetable(SPL_result_LMSlog,'SPL_result_LMSlog.txt'); 
writetable(SPL_result_LMSlin,'SPL_result_LMSlin.txt'); 
writetable(SPL_result_LMSlog2,'SPL_result_LMSlog2.txt'); 
writetable(SPL_result_LMSlin2,'SPL_result_LMSlin2.txt'); 

